inputs = ['ajwuce', 'iu', 'hxybik', 'hjibd', 'yuaxcc']
outputs = ['ajwuce', 'iihu', 'hxybiihxf', 'huezbd', 'yuaxcc']

# Let's compare each pair character by character
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"Pair {i}: '{inp}' -> '{out}'")
    if inp != out:
        # Find differences
        min_len = min(len(inp), len(out))
        for j in range(min_len):
            if inp[j] != out[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{out[j]}'")
        if len(inp) != len(out):
            print(f"  Length changed: {len(inp)} -> {len(out)}")
    print()

